import { Difficulty } from '../types/game';
import { CompactWordInput, RawWordSeed } from './wordFactory';

/**
 * =========================================================================
 * بانک جامع و یکپارچه کلمات ادابازی (wordDB.ts)
 * =========================================================================
 * تمام ۱۹ دسته‌بندی اصلی (در ۳ سطح easy / medium / hard) و عبارات موضوع طلایی (golden)
 * به صورت یکجا در همین فایل قرار دارند و کل بازی از همین فایل تغذیه می‌شود.
 *
 * راهنمای افزودن یا ویرایش سریع کلمات:
 * ۱. به بخش دسته‌بندی موردنظر (مثلاً football.easy، movies_series.medium، celebrities.hard یا golden) بروید.
 * ۲. عبارت جدید را داخل آرایه اضافه کنید؛ مثلاً:
 *      'یک کلمه جدید',
 * ۳. در بخش فوتبال و سلبریتی هم می‌توانید رشته ساده بنویسید و هم از شورتکات‌های زیر استفاده کنید:
 *      fp('نام بازیکن خارجی') | ip('نام بازیکن ایرانی') | fo('اصطلاح فوتبالی')
 *      ic('نام چهره ایرانی', 'حرفه') | fc('نام چهره خارجی', 'حرفه')
 * ۴. نیازی به تغییر هیچ فایل دیگری نیست؛ شناسه‌ها، امتیازات، زمان تایمر و همگام‌سازی
 *    دیتابیس آفلاین مرورگر به صورت کاملاً خودکار انجام می‌شود.
 */

const fp = (text: string, tags: string[] = ['بازیکن خارجی'], alt: string[] = []): RawWordSeed => ({
  text,
  origin: 'foreign',
  footballSubType: 'player',
  tags,
  alt,
});

const ip = (text: string, tags: string[] = ['بازیکن ایرانی'], alt: string[] = []): RawWordSeed => ({
  text,
  origin: 'iranian',
  footballSubType: 'player',
  tags,
  alt,
});

const fo = (
  text: string,
  origin: 'iranian' | 'foreign' | 'neutral' = 'neutral',
  tags: string[] = ['موضوع فوتبالی'],
  alt: string[] = []
): RawWordSeed => ({
  text,
  origin,
  footballSubType: 'other',
  tags,
  alt,
});

const ic = (text: string, roleTag = 'چهره شناخته‌شده', alt: string[] = []): RawWordSeed => ({
  text,
  origin: 'iranian',
  tags: ['سلبریتی ایرانی', roleTag],
  alt,
});

const fc = (text: string, roleTag = 'چهره جهانی', alt: string[] = []): RawWordSeed => ({
  text,
  origin: 'foreign',
  tags: ['سلبریتی خارجی', roleTag],
  alt,
});

export type RegularCategoryId =
  | 'general'
  | 'kids'
  | 'football'
  | 'sports'
  | 'movies_series'
  | 'cartoons'
  | 'celebrities'
  | 'famous_figures'
  | 'books'
  | 'music'
  | 'places'
  | 'cities_countries'
  | 'proverbs'
  | 'abstract'
  | 'animals'
  | 'food'
  | 'jobs'
  | 'objects'
  | 'tech_science';

export type LocalWordDatabase = Record<RegularCategoryId, Record<Difficulty, CompactWordInput[]>> & {
  golden: CompactWordInput[];
};

